-- Create "model_rates" table
CREATE TABLE `model_rates` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `team_id` varchar(32) NOT NULL, `config_id` varchar(32) NOT NULL, `provider` varchar(400) NOT NULL, `model` varchar(400) NOT NULL, `revision` bigint NOT NULL, `basis` enum('cost','weight') NOT NULL, `input_rate` bigint NOT NULL, `cache_read_rate` bigint NOT NULL, `cache_write_rate` bigint NOT NULL, `output_rate` bigint NOT NULL, `actor_id` varchar(32) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `modelrate_team_id_config_id_revision` (`team_id`, `config_id`, `revision`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "usage_requests" table
CREATE TABLE `usage_requests` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `team_id` varchar(32) NOT NULL, `user_id` varchar(32) NOT NULL, `submitted_config_id` varchar(32) NOT NULL, `config_id` varchar(32) NOT NULL, `provider` varchar(400) NOT NULL, `model` varchar(400) NOT NULL, `stream` bool NOT NULL, `state` enum('running','settled','unpriced','pending','failed') NOT NULL DEFAULT "running", `rate_id` varchar(32) NOT NULL DEFAULT "", `rates` json NULL, `point_units` bigint NULL, `input_tokens` bigint NULL, `cache_read_tokens` bigint NULL, `cache_write_tokens` bigint NULL, `output_tokens` bigint NULL, `reasoning_tokens` bigint NULL, `provider_request_id` varchar(200) NOT NULL DEFAULT "", `error_code` varchar(64) NOT NULL DEFAULT "", `finished_at` datetime(6) NULL, PRIMARY KEY (`id`), INDEX `usagerequest_state_created_at` (`state`, `created_at`), INDEX `usagerequest_team_id_config_id_created_at` (`team_id`, `config_id`, `created_at`), INDEX `usagerequest_team_id_created_at` (`team_id`, `created_at`), INDEX `usagerequest_team_id_user_id_created_at` (`team_id`, `user_id`, `created_at`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
